    int64_t* new_indices = (int64_t*)z_xmalloc(new_cap * sizeof(int64_t));
    for (uint64_t i = 0; i < new_cap; i++) {
        new_indices[i] = Z_T2397_INDEX_EMPTY;
    }
    z_t2397_entry_t* new_entries = (z_t2397_entry_t*)z_xcalloc(new_cap, sizeof(z_t2397_entry_t));
    uint64_t new_entries_len = 0;
